using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
namespace Nexus {
  public static class PortRemovalTests {
    static int checks;static void Check(bool value,string message){if(!value)throw new Exception("Removal: "+message);checks++;}
    static void Reject(Action action,string message){try{action();}catch{checks++;return;}throw new Exception("Removal expected rejection: "+message);}
    static Game Fixture(string parent,string name,bool managed){string root=Path.Combine(parent,name);Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"Game.exe"),"owned fixture");Directory.CreateDirectory(Path.Combine(root,"assets"));File.WriteAllText(Path.Combine(root,"assets","own-dump.dat"),"own fixture dump");var g=new Game{Name=name,Executable=Path.Combine(root,"Game.exe"),Repository="test/removal",InstalledVersion="v1",ManagedInstallationRoot=managed?root:null};if(managed)UpdateManager.WriteReceipt(new PortEntry{Repository=g.Repository},new PortRelease{Version="v1",AssetName="fixture.zip"},root,CancellationToken.None);return g;}
    public static int Run(string root){
      checks=0;string parent=Path.Combine(root,"removal-fixtures"),data=Path.Combine(root,"library-data");Directory.CreateDirectory(parent);Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"library.json"),"keep library");
      var managed=Fixture(parent,"managed-copy",true);var list=new List<Game>{managed};string install=managed.ManagedInstallationRoot;string backup=install+".nexus-backup-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(backup);File.WriteAllText(Path.Combine(backup,"old.exe"),"owned old binary");UpdateManager.WriteReceipt(new PortEntry{Repository=managed.Repository},new PortRelease{Version="v0",AssetName="fixture.zip"},backup,CancellationToken.None);
      string unrelated=install+".nexus-backup-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(unrelated);File.WriteAllText(Path.Combine(unrelated,"personal.txt"),"keep unverified");
      string source=Path.Combine(root,"original-dump");Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"own.iso"),"original");managed.GameContentSource=source;
      var plan=PortRemoval.Build(managed,list,data,null,true);Check(plan.Roots.Length==2&&plan.Roots.Contains(backup)&&!plan.Roots.Contains(unrelated)&&plan.FileCount>0&&plan.Bytes>0,"only matching receipt-backed backups included");Check(File.Exists(managed.Executable),"planning and cancellation do not delete anything");PortRemoval.Execute(plan,null);Check(!Directory.Exists(install)&&!Directory.Exists(backup),"managed installation and confirmed backup removed completely");Check(File.Exists(Path.Combine(source,"own.iso"))&&File.Exists(Path.Combine(unrelated,"personal.txt"))&&File.ReadAllText(Path.Combine(data,"library.json"))=="keep library","external dump, unrelated folder and library preserved");
      var manual=Fixture(parent,"manual-copy",false);list=new List<Game>{manual};Reject(()=>PortRemoval.Build(manual,list,data,null,true),"manual root must be explicitly selected");Reject(()=>PortRemoval.Build(manual,list,data,source,true),"chosen root must contain registered executable");plan=PortRemoval.Build(manual,list,data,Path.GetDirectoryName(manual.Executable),false);Check(plan.Roots.Length==1,"manual folder selected explicitly");string changed=Path.Combine(plan.Roots[0],"added-after-confirmation.txt");File.WriteAllText(changed,"new personal data");Reject(()=>PortRemoval.Execute(plan,null),"changes after confirmation require review");Check(File.Exists(manual.Executable)&&File.Exists(changed),"changed folder left untouched");
      var other=new Game{Name="Another port",Executable=Path.Combine(plan.Roots[0],"shared.exe")};list.Add(other);Reject(()=>PortRemoval.Build(manual,list,data,plan.Roots[0],true),"shared registered executable");other.Executable=Path.Combine(source,"other.exe");other.GameContentSource=Path.Combine(plan.Roots[0],"assets");Reject(()=>PortRemoval.Build(manual,list,data,plan.Roots[0],true),"another games source files protected");list.Remove(other);
      Reject(()=>PortRemoval.ValidateRoot(data,manual,list,data),"library directory protected");Reject(()=>PortRemoval.ValidateRoot(parent,manual,new[]{manual,new Game{Name="Sibling port",Executable=Path.Combine(parent,"sibling","Other.exe")}},data),"parent containing unrelated registered references or protected scope");
      Reject(()=>PortRemoval.ValidateRoot(Path.GetDirectoryName(SelfUpdater.CurrentExe),manual,list,data),"NEXUS application protected");Reject(()=>PortRemoval.ValidateRoot(Path.GetPathRoot(root),manual,list,data),"drive root protected");Reject(()=>PortRemoval.ValidateRoot(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),manual,list,data),"user profile protected");
      var shortcut=manual.Copy();shortcut.Executable=Path.Combine(parent,"Desktop shortcut.lnk");Reject(()=>PortRemoval.Build(shortcut,new[]{shortcut},data,parent,true),"shortcut folder never inferred as game install");Check(!PortRemoval.Within(plan.Roots[0],plan.Roots[0]+"-sibling\\file.dat"),"path boundaries cannot match sibling prefixes");
      plan=PortRemoval.Build(manual,list,data,Path.GetDirectoryName(manual.Executable),false);using(var held=new FileStream(manual.Executable,FileMode.Open,FileAccess.ReadWrite,FileShare.None))Reject(()=>PortRemoval.Execute(plan,null),"locked files stop removal before changes");Check(File.Exists(manual.Executable)&&File.Exists(changed),"locked preflight preserved full installation");File.SetAttributes(changed,FileAttributes.ReadOnly);plan=PortRemoval.Build(manual,list,data,Path.GetDirectoryName(manual.Executable),false);PortRemoval.Execute(plan,null);Check(!Directory.Exists(Path.GetDirectoryName(manual.Executable)),"manual folder and read-only port files removed");
      var installer=Fixture(parent,"generated-game",false);installer.InstallationKind="Installer";var cache=Fixture(parent,"author-setup-cache",true);installer.InstallerCacheRoot=cache.ManagedInstallationRoot;installer.Repository=cache.Repository;installer.InstalledVersion=cache.InstalledVersion;plan=PortRemoval.Build(installer,new[]{installer},data,Path.GetDirectoryName(installer.Executable),true);Check(plan.Roots.Length==2&&plan.Roots.Contains(installer.InstallerCacheRoot),"author-generated game folder and verified cache included");PortRemoval.Execute(plan,null);Check(!Directory.Exists(Path.GetDirectoryName(installer.Executable))&&!Directory.Exists(cache.ManagedInstallationRoot),"author install confirmed folders removed");
      var partial=Fixture(parent,"partial-failure",true);for(int i=0;i<100;i++)File.WriteAllText(Path.Combine(partial.ManagedInstallationRoot,"fixture-"+i+".dat"),"owned");plan=PortRemoval.Build(partial,new[]{partial},data,null,false);Reject(()=>PortRemoval.Execute(plan,new FailProgress()),"mid-removal failure reported");Check(Directory.Exists(partial.ManagedInstallationRoot)&&File.Exists(partial.Executable)&&!Directory.GetDirectories(parent,".nexus-delete-*").Any(),"remaining files restored to visible original location after failure");
      return checks;
    }
    class FailProgress:IProgress<InstallProgress>{public void Report(InstallProgress p){throw new IOException("fixture deletion interrupted");}}
  }
}
